<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090d18;
        --panel: #111827;
        --panel-soft: #172033;
        --text: #f8fafc;
        --muted: #a7b0c0;
        --accent: #7c3aed;
        --accent-strong: #a78bfa;
        --border: #334155;
        --focus: #38bdf8;
        --shadow: rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 32px 18px;
        background:
          radial-gradient(circle at top left, rgba(124, 58, 237, 0.32), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(56, 189, 248, 0.18), transparent 28rem),
          var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .support-card {
        width: min(100%, 560px);
        padding: 32px;
        border: 1px solid rgba(148, 163, 184, 0.2);
        border-radius: 28px;
        background: linear-gradient(145deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.92));
        box-shadow: 0 24px 80px var(--shadow);
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--accent-strong);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3rem);
        line-height: 1.05;
      }

      .intro {
        margin: 16px 0 28px;
        color: var(--muted);
        font-size: 1rem;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 700;
      }

      .optional {
        color: var(--muted);
        font-size: 0.9rem;
        font-weight: 500;
      }

      input {
        width: 100%;
        min-height: 52px;
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 0 16px;
        background: var(--panel-soft);
        color: var(--text);
        font: inherit;
        outline: none;
        transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
      }

      input::placeholder {
        color: #778195;
      }

      input:focus {
        border-color: var(--focus);
        background: #1d2940;
        box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.2);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
      }

      button {
        min-height: 54px;
        margin-top: 4px;
        border: 0;
        border-radius: 16px;
        background: linear-gradient(135deg, var(--accent), #2563eb);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: 0.01em;
        box-shadow: 0 14px 32px rgba(79, 70, 229, 0.3);
        transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        filter: brightness(1.08);
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      button:active {
        transform: translateY(0);
      }

      @media (max-width: 520px) {
        .support-card {
          padding: 24px;
          border-radius: 22px;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Jordan Lee",
          required: true
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          helperText: "Use country code and spaces, for example +1 555 123 4567.",
          required: false
        }
      ];

      function Field({ id, name, label, type, autocomplete, placeholder, helperText, required }) {
        const field = document.createElement("div");
        const input = document.createElement("input");
        const fieldLabel = document.createElement("label");

        field.className = "form-field";
        fieldLabel.htmlFor = id;
        fieldLabel.textContent = label;

        if (!required) {
          const optional = document.createElement("span");
          optional.className = "optional";
          optional.textContent = " optional";
          fieldLabel.append(optional);
        }

        input.id = id;
        input.name = name;
        input.type = type;
        input.autocomplete = autocomplete;
        input.placeholder = placeholder;
        input.required = required;

        field.append(fieldLabel, input);

        if (helperText) {
          const helper = document.createElement("p");
          const helperId = `${id}-hint`;
          helper.id = helperId;
          helper.className = "helper-text";
          helper.textContent = helperText;
          input.setAttribute("aria-describedby", helperId);
          field.append(helper);
        }

        return field;
      }

      function SupportContactForm() {
        const card = document.createElement("section");
        const eyebrow = document.createElement("p");
        const heading = document.createElement("h1");
        const intro = document.createElement("p");
        const form = document.createElement("form");
        const submit = document.createElement("button");

        card.className = "support-card";
        card.setAttribute("aria-labelledby", "support-heading");

        eyebrow.className = "eyebrow";
        eyebrow.textContent = "Support";

        heading.id = "support-heading";
        heading.textContent = "How can we help?";

        intro.className = "intro";
        intro.textContent = "Send your contact details and our support team will get back to you.";

        form.action = "#";
        form.method = "post";
        form.noValidate = false;

        fields.forEach((field) => form.append(Field(field)));

        submit.type = "submit";
        submit.textContent = "Contact support";
        form.append(submit);

        card.append(eyebrow, heading, intro, form);
        return card;
      }

      function App() {
        const root = document.createDocumentFragment();
        root.append(SupportContactForm());
        return root;
      }

      document.getElementById("root").append(App());
    </script>
  </body>
</html>
