        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 0 16px;
        background: var(--panel-soft);
        color: var(--text);
        font: inherit;
        outline: none;
        transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
      }

