      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 700;
      }

      .optional {
        color: var(--muted);
        font-size: 0.9rem;
        font-weight: 500;
      }

      input {
        width: 100%;
        min-height: 52px;
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 0 16px;
        background: var(--panel-soft);
        color: var(--text);
        font: inherit;
        outline: none;
        transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
      }

      input::placeholder {
        color: #778195;
      }

      input:focus {
        border-color: var(--focus);
        background: #1d2940;
        box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.2);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
      }

      button {
        min-height: 54px;
        margin-top: 4px;
        border: 0;
        border-radius: 16px;
        background: linear-gradient(135deg, var(--accent), #2563eb);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: 0.01em;
        box-shadow: 0 14px 32px rgba(79, 70, 229, 0.3);
        transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        filter: brightness(1.08);
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      button:active {
        transform: translateY(0);
      }

      @media (max-width: 520px) {
        .support-card {
          padding: 24px;
          border-radius: 22px;
        }
      }
    </style>
  </head>
  <body>
    <main id="root">
      <section class="support-card" aria-labelledby="support-heading">
        <p class="eyebrow">Support</p>
        <h1 id="support-heading">How can we help?</h1>
        <p class="intro">Send your contact details and our support team will get back to you.</p>

        <form action="#" method="post">
          <div class="form-field">
            <label for="full-name">Full name</label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              placeholder="Jordan Lee"
              required
            >
          </div>

          <div class="form-field">
            <label for="email-address">Email address</label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              placeholder="jordan@example.com"
              required
            >
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span class="optional">optional</span></label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              placeholder="+1 555 123 4567"
              aria-describedby="phone-number-hint"
            >
            <p id="phone-number-hint" class="helper-text">Use country code and spaces, for example +1 555 123 4567.</p>
          </div>

          <button type="submit">Contact support</button>
        </form>
      </section>
    </main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Jordan Lee",
          required: true
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          helperText: "Use country code and spaces, for example +1 555 123 4567.",
          required: false
        }
      ];

      function Field({ id, name, label, type, autocomplete, placeholder, helperText, required }) {
        const field = document.createElement("div");
        const input = document.createElement("input");
        const fieldLabel = document.createElement("label");

        field.className = "form-field";
        fieldLabel.htmlFor = id;
        fieldLabel.textContent = label;

        if (!required) {
          const optional = document.createElement("span");
          optional.className = "optional";
          optional.textContent = " optional";
          fieldLabel.append(optional);
        }

        input.id = id;
        input.name = name;
        input.type = type;
        input.autocomplete = autocomplete;
        input.placeholder = placeholder;
        input.required = required;

        field.append(fieldLabel, input);

        if (helperText) {
          const helper = document.createElement("p");
          const helperId = `${id}-hint`;
          helper.id = helperId;
          helper.className = "helper-text";
          helper.textContent = helperText;
          input.setAttribute("aria-describedby", helperId);
          field.append(helper);
        }

        return field;
      }

      function SupportContactForm() {
        const card = document.createElement("section");
        const eyebrow = document.createElement("p");
        const heading = document.createElement("h1");
        const intro = document.createElement("p");
        const form = document.createElement("form");
        const submit = document.createElement("button");

        card.className = "support-card";
        card.setAttribute("aria-labelledby", "support-heading");

        eyebrow.className = "eyebrow";
        eyebrow.textContent = "Support";

        heading.id = "support-heading";
        heading.textContent = "How can we help?";

        intro.className = "intro";
        intro.textContent = "Send your contact details and our support team will get back to you.";

        form.action = "#";
        form.method = "post";
        form.noValidate = false;

        fields.forEach((field) => form.append(Field(field)));

        submit.type = "submit";
        submit.textContent = "Contact support";
        form.append(submit);

        card.append(eyebrow, heading, intro, form);
        return card;
      }

      function App() {
        return SupportContactForm;
      }
    </script>
  </body>
</html>
